1	public func parseCmdArgs(_ args: StrArrSlice) -> ParsedCmd<any CmdArgs> {
2	    let subcommand = String(args.first ?? "")
3	    if subcommand.isEmpty {
4	        return .failure("Can't parse empty string command", EXIT_CODE_TWO)
5	    }
6	    if let subcommandParser: any SubCommandParserProtocol = subcommandParsers[subcommand] {
7	        return subcommandParser.parse(args: args.slice(1...).orDie())
8	    } else {
9	        return .failure("Unrecognized subcommand '\(subcommand)'", EXIT_CODE_TWO)
10	    }
11	}
