1	func parseSpecificCmdArgs<T: CmdArgs>(_ raw: T, _ args: StrArrSlice) -> ParsedCmd<T> {
2	    var raw = raw
3	    var errors: [String] = []
4	
5	    var posArgumentParserIndex = 0
6	    var options: Set<String> = Set()
7	    var index = 0
8	    var positionalOnly = false
9	
10	    loop: while index < args.count {
11	        let arg = args[index]
12	
13	        switch (positionalOnly, arg) {
14	            case (false, "-h"), (false, "--help"):
15	                return .help(T.info.help)
16	            case (false, _) where arg.isCliDashFlag && !isResizeNegativeUnitsArg(raw, arg: arg):
17	                if let optionParser = T.parser.flags[arg] {
18	                    index += 1
19	                    if !options.insert(arg).inserted {
20	                        errors.append("Duplicated option \(arg.singleQuoted)")
21	                    }
22	                    raw = optionParser.transformRaw(raw, &index, SubArgParserInput(superArg: arg, index: index, args: args), &errors)
23	                } else {
24	                    errors.append("Unknown flag \(arg.singleQuoted)")
25	                    break loop
26	                }
27	            default:
28	                if arg == "--" {
29	                    positionalOnly = true
30	                }
31	                if let parser = T.parser.positionalArgs.getOrNil(atIndex: posArgumentParserIndex) {
32	                    let input = PosArgParserInput(index: index, args: args, sawDashDash: positionalOnly)
33	                    raw = parser.transformRaw(raw, &index, input, &errors)
34	                    posArgumentParserIndex += 1
35	                } else {
36	                    errors.append("Unknown argument \(arg.singleQuoted)")
37	                    break loop
38	                }
39	        }
40	    }
41	
42	    for arg in T.parser.positionalArgs[posArgumentParserIndex...] {
43	        if let placeholder = arg.context.argPlaceholderIfMandatory {
44	            errors.append("Argument \(placeholder.singleQuoted) is mandatory")
45	        }
46	    }
47	
48	    for conflictSet in T.parser.conflictingOptions {
49	        let mutualOptions = conflictSet.intersection(options)
50	        if mutualOptions.count > 1 {
51	            errors.append("Conflicting options: \(mutualOptions.sorted().joined(separator: ", "))")
52	            break
53	        }
54	    }
55	
56	    return errors.isEmpty ? .cmd(raw) : .failure(errors.joinErrors())
57	}
