22	func singleValueSubArgParser<Root, Value>(
23	    _ keyPath: SendableWritableKeyPath<Root, Value?>,
24	    _ placeholder: String,
25	    _ mapper: @escaping @Sendable (String) -> ResOrStr<Value>,
26	) -> SubArgParser<Root, Value?> {
27	    ArgParser(keyPath) { input in
28	        switch input.nonFlagArgOrNil() {
29	            case nil: .fail("'\(input.superArg)' must be followed by '\(placeholder)'", advanceBy: 0)
30	            case let arg?:
31	                switch mapper(arg) {
32	                    case .success(let value): .succ(value, advanceBy: 1)
33	                    case .failure(let error): .fail("Failed to parse '\(arg)' CLI argument: \(error)", advanceBy: 1)
34	                }
35	        }
36	    }
37	}
