3	func parseCommand(
4	    _ raw: String,
5	    allowExecAndForget: Bool,
6	    allowEval: Bool,
7	) -> ParsedCmd<Shell<any Command>> {
8	    if allowExecAndForget && raw.starts(with: "exec-and-forget") {
9	        return .cmd(.cmd(ExecAndForgetCommand(args: ExecAndForgetCmdArgs(bashScript: raw.removePrefix("exec-and-forget")))))
10	    }
11	    return switch raw.lexAndParseShell() {
12	        case .success(let it):
13	            it.flatMap { args in
14	                switch parseCommand(args) {
15	                    case .cmd(_ as EvalCommand) where !allowEval: .failure("Illegal eval (Tip: nested evals are forbidden)", EXIT_CODE_TWO)
16	                    case .cmd(let it): .cmd(it)
17	                    case .failure(let it): .failure(it)
18	                    case .help(let it): .help(it)
19	                }
20	            }
21	        case .failure(let it): ParsedCmd.failure(it, EXIT_CODE_TWO)
22	    }
23	}
