4	struct FlattenWorkspaceTreeCommand: Command {
5	    let args: FlattenWorkspaceTreeCmdArgs
6	    /*conforms*/ let shouldResetClosedWindowsCache: Bool = true
7	
8	    func run(_ env: CmdEnv, _ io: CmdIo) -> BinaryExitCode {
9	        guard let target = args.resolveTargetOrReportError(env, io) else { return .fail }
10	        let workspace = target.workspace
11	        let windows = workspace.rootTilingContainer.allLeafWindowsRecursive
12	        for window in windows {
