43	    func buildDescription(_ stringifier: (T) -> String) -> String {
44	        let parentPrecedence = precedence
45	        func render(_ child: Shell<T>) -> String {
46	            let desc = child.buildDescription(stringifier)
47	            return child.precedence < parentPrecedence ? "(\(desc))" : desc
48	        }
49	        return switch self {
50	            case .empty: ""
51	            case .cmd(let cmd): stringifier(cmd)
52	            case .pipe(let it): it.map(render).joined(separator: " | ")
53	            case .and(let it): it.map(render).joined(separator: " && ")
54	            case .or(let it): it.map(render).joined(separator: " || ")
55	            case .seq(let it): it.map(render).joined(separator: "; ")
56	        }
57	    }
