98	extension Shell where T == any Command {
99	    @MainActor func run(_ env: CmdEnv, _ io: CmdIo) async -> Int32ExitCode {
100	        switch self {
101	            case .cmd(let command):
102	                let exitCode = Int32ExitCode(rawValue: await command.run(env, io).rawValue)
103	                if command.shouldResetClosedWindowsCache { resetClosedWindowsCache() }
