106	            case .and(let commands): return await runShellAnd(commands, env, io)
107	            case .empty: return Int32ExitCode(rawValue: EXIT_CODE_ZERO)
108	            case .or(let commands): return await runShellOr(commands, env, io)
109	            case .pipe(let commands): return await runShellPipe(commands, env, io)
110	            case .seq(let commands): return await runShellSeq(commands, env, io)
111	        }
