131	    var exitCode = Int32ExitCode(rawValue: EXIT_CODE_ZERO)
132	    for command in commands {
133	        exitCode = await command.run(env, io)
134	        if exitCode.rawValue != 0 { break }
135	    }
136	    return exitCode
