139	@MainActor private func runShellSeq(_ commands: [Shell<any Command>], _ env: CmdEnv, _ io: CmdIo) async -> Int32ExitCode {
140	    var exitCode = Int32ExitCode(rawValue: EXIT_CODE_ZERO)
141	    for command in commands {
