147	/// runs commands sequentially, buffering the entire stdout between them and joining with \n before re-feeding as stdin.
148	/// For long-running or streaming commands this would matter, but AeroSpace's commands are short and synchronous, so this is fine
149	///
150	/// The semantics is similar to 'set -o pipefail'
151	@MainActor private func runShellPipe(_ commands: [Shell<any Command>], _ env: CmdEnv, _ originalIo: CmdIo) async -> Int32ExitCode {
152	    var rightmostNonZeroExitCode = Int32ExitCode(rawValue: EXIT_CODE_ZERO)
153	    var io: CmdIo = CmdIoForwardingStdin(stdin: originalIo)
154	    var lastStdout = [String]()
155	    for command in commands {
156	        let exitCode = await command.run(env, io)
157	        originalIo.stderr += io.stderr
158	        lastStdout = io.stdout
159	        io = CmdIoImpl(stdin: .init(lastStdout.joined(separator: "\n")))
160	        if exitCode.rawValue != 0 {
161	            rightmostNonZeroExitCode = exitCode
162	        }
163	    }
164	    originalIo.out(lastStdout)
165	    return rightmostNonZeroExitCode
166	}
