### 1b. `Command` — `/Users/bogac/dev/forgejo/AeroSpace/Sources/AppBundle/command/Command.swift` (whole file)

```swift
import AppKit
import Common

protocol Command: AeroAny, Equatable, Sendable {
    associatedtype T: CmdArgs

    var args: T { get }
    @MainActor
    func run(_ env: CmdEnv, _ io: CmdIo) async -> T.ExitCodeType

    /// We should reset closedWindowsCache when the command can potentially change the tree
    var shouldResetClosedWindowsCache: Bool { get }
}

extension Command {
    static func == (lhs: Self, rhs: Self) -> Bool {
        return lhs.args.equals(rhs.args)
    }

    nonisolated func equals(_ other: any Command) -> Bool {
        (other as? Self).flatMap { self == $0 } ?? false
    }
}

extension Command {
    var info: CmdStaticInfo { T.info }
}

extension Command {
    @MainActor
    @discardableResult
    func run(_ env: CmdEnv, _ stdin: consuming CmdStdin) async -> CmdResult {
        return await Shell.cmd(self).run(env, stdin)
    }
}
```

Note: `Command` is **internal**, not `public`. Its impls are internal `struct`s in `AppBundle`.

**Critical practical detail about the `run` witness.** The requirement is `@MainActor ... async`, but almost every implementation writes neither keyword:

```swift
func run(_ env: CmdEnv, _ io: CmdIo) -> BinaryExitCode {
```

This compiles because Swift infers global-actor isolation for a declaration that witnesses a `@MainActor` requirement, and a synchronous function can witness an `async` requirement. Both shapes are legal and both are used in-tree — `grep` over `Sources/AppBundle/command/impl/*.swift` shows 21 sync and 23 `async` witnesses. Write `async` only if your body needs `await`.

Return type must be `T.ExitCodeType`. Defined in `/Users/bogac/dev/forgejo/AeroSpace/Sources/Common/cmdArgs/ExitCode.swift`:

```swift
public protocol ExitCode: RawRepresentable<Int32>, AeroAny, Sendable {
    static var fail: Self { get }
}

extension ExitCode {
    public static func fail(_ _: IoSideEffect) -> Self { .fail }
}

public let EXIT_CODE_ZERO: Int32 = 0
public let EXIT_CODE_TWO: Int32 = 2

public struct Int32ExitCode: ExitCode, Equatable {
    public var rawValue: Int32
    public init(rawValue: Int32) { self.rawValue = rawValue }
    public static let fail = Int32ExitCode(rawValue: EXIT_CODE_TWO)
    public static let succ = Int32ExitCode(rawValue: EXIT_CODE_TWO)
}

public enum BinaryExitCode: Int32, ExitCode {
    case succ = 0
    case fail = 2
    public static func from(bool: Bool) -> Self { bool ? .succ : .fail }

    public static func succ(_ _: IoSideEffect) -> Self { .succ }

    public func and(_ other: @autoclosure () -> Self) -> Self {
        switch rawValue {
            case EXIT_CODE_ZERO: other()
            default: self
        }
    }

    // periphery:ignore
    public func or(_ other: @autoclosure () -> Self) -> Self {
        switch rawValue {
            case EXIT_CODE_ZERO: self
            default: other()
        }
    }
}

public enum ConditionalExitCode: Int32, ExitCode {
    case _true = 0
    case _false = 1
    case fail = 2
}

public enum IoSideEffect { case instance }
```

Default is `BinaryExitCode` (from the `associatedtype ... = BinaryExitCode` default). Override with `public typealias ExitCodeType = ConditionalExitCode` inside the CmdArgs struct — see `TestCmdArgs` below.

`.fail(io.err("msg"))` / `.succ(io.err("msg"))` are the idiom for "return this code, and as a side effect write to stderr" — that's what `IoSideEffect` exists for.

