### 1e. Resolving the target window/workspace — `/Users/bogac/dev/forgejo/AeroSpace/Sources/AppBundle/command/cmdResolveTargetOrReportError.swift`

This is the "what am I acting on" helper every tree-touching command calls first. Precedence: `--window-id` flag → `--workspace` flag → `AEROSPACE_WINDOW_ID` env → `AEROSPACE_WORKSPACE` env → real focus.

```swift
extension CmdArgs {
    @MainActor
    var workspace: Workspace? {
        if let workspaceName { Workspace.get(byName: workspaceName.raw) } else { nil }
    }

    @MainActor
    func resolveTargetOrReportError(_ env: CmdEnv, _ io: CmdIo) -> LiveFocus? {
        // Flags
        if let windowId {
            if let wi = Window.get(byId: windowId) {
                return wi.toLiveFocusOrReportError(io)
            } else {
                io.err("Invalid <window-id> \(windowId) passed to --window-id")
                return nil
            }
        }
        if let workspace {
            return workspace.toLiveFocus()
        }
        // Env
        if let windowId = env.windowId { ... }
        if let wsName = env.workspaceName {
            return Workspace.get(byName: wsName).toLiveFocus()
        }
        // Real Focus
        return focus
    }
}
```

### 1f. How `run` is actually invoked

`/Users/bogac/dev/forgejo/AeroSpace/Sources/AppBundle/shell/Shell.swift` lines 93–118:

```swift
// There are 4 entry points for running commands:
// 1. config keybindings
// 2. CLI requests to server
// 3. on-window-detected callback
// 4. Tray icon buttons
extension Shell where T == any Command {
    @MainActor func run(_ env: CmdEnv, _ io: CmdIo) async -> Int32ExitCode {
        switch self {
            case .cmd(let command):
                let exitCode = Int32ExitCode(rawValue: await command.run(env, io).rawValue)
                if command.shouldResetClosedWindowsCache { resetClosedWindowsCache() }
                await refreshModel_nonCancellable()
                return exitCode
            case .and(let commands): return await runShellAnd(commands, env, io)
            case .empty: return Int32ExitCode(rawValue: EXIT_CODE_ZERO)
            case .or(let commands): return await runShellOr(commands, env, io)
            case .pipe(let commands): return await runShellPipe(commands, env, io)
            case .seq(let commands): return await runShellSeq(commands, env, io)
        }
    }

    @discardableResult @MainActor func run(_ env: CmdEnv, _ stdin: consuming CmdStdin) async -> CmdResult {
        let io: CmdIo = CmdIoImpl(stdin: stdin)
        let exitCode = await run(env, io)
        return CmdResult(stdout: io.stdout, stderr: io.stderr, exitCode: exitCode)
    }
}
```

