### Step 2 — `initSubcommands()` case
Same file, lines 55–156. Exhaustive `switch kind`:

```swift
func initSubcommands() -> [String: any SubCommandParserProtocol] {
    var result: [String: any SubCommandParserProtocol] = [:]
    for kind in CmdKind.allCases {
        switch kind {
            case .balanceSizes:
                result[kind.rawValue] = SubCommandParser(BalanceSizesCmdArgs.init)
            ...
            case .execAndForget:
                break // exec-and-forget is parsed separately
            ...
            case .move:
                result[kind.rawValue] = SubCommandParser(parseMoveCmdArgs)
                // deprecated
                result["move-through"] = SubCommandParser(parseMoveCmdArgs)
            ...
        }
    }
    return result
}
```

Two overloads pick which form you use — `/Users/bogac/dev/forgejo/AeroSpace/Sources/Common/cmdArgs/subcommandParsers.swift` (whole file):

```swift
let subcommandParsers: [String: any SubCommandParserProtocol] = initSubcommands()

protocol SubCommandParserProtocol<T>: Sendable {
    associatedtype T where T: CmdArgs
    var _parse: @Sendable (StrArrSlice) -> ParsedCmd<T> { get }
}

extension SubCommandParserProtocol {
    func parse(args: StrArrSlice) -> ParsedCmd<any CmdArgs> { _parse(args).map(id) }
}

struct SubCommandParser<T: CmdArgs>: SubCommandParserProtocol, Sendable {
    let _parse: @Sendable (StrArrSlice) -> ParsedCmd<T>

    init(_ parser: @escaping @Sendable (StrArrSlice) -> ParsedCmd<T>) {
        _parse = parser
    }

    init(_ raw: @escaping @Sendable (StrArrSlice) -> T) {
        _parse = { args in parseSpecificCmdArgs(raw(args), args) }
    }
}
```

Pass `MyCmdArgs.init` when you need no cross-flag validation; pass a `parseMyCmdArgs` free function returning `ParsedCmd<MyCmdArgs>` when you do (it calls `parseSpecificCmdArgs` then chains `.filter`/`.filterNot`).

